style.css:
@-moz-document domain("snopes.com") {
html {
  color-scheme: dark !important;
  color: #d9ffe6 !important;
  background-color: #0a0a0a !important;
  /* Entirely CSS-generated wallpaper: no image URLs or encoded assets. */
  /* Thin pale-green grid at 40px intervals, plus faint 4px CRT scan lines. */
  background-image:
    linear-gradient(to right, rgba(130,255,167,.13) 1px, transparent 1px),
    linear-gradient(to bottom, rgba(130,255,167,.13) 1px, transparent 1px),
    repeating-linear-gradient(to bottom,
      rgba(10,10,10,0) 0px,
      rgba(10,10,10,0) 3px,
      rgba(105,255,153,.035) 3px,
      rgba(105,255,153,.035) 4px) !important;
  background-size: 40px 40px, 40px 40px, 100% 4px !important;
  background-position: 0 0 !important;
  background-repeat: repeat !important;
  background-attachment: fixed !important;
}

/* Clear the page shell so the fixed grid remains visible. */
body, #app, #root, #__next, #page, #wrapper, #content, #main,
.site-wrapper, .page-wrapper, .site-content, .main-content,
main, [role="main"] {
  background-color: transparent !important;
  background-image: none !important;
  color: #d9ffe6 !important;
}

/* Explicit typography on editorial text and controls preserves icon fonts. */
html, body, h1, h2, h3, h4, h5, h6, p, li, dt, dd, time,
label, summary, blockquote, figcaption, caption, th, td, pre, code, kbd,
button, input, select, textarea, [role="button"], [role="menuitem"],
[role="option"], [role="tab"], [contenteditable="true"],
nav a, header a, footer a, main a {
  font-family: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", "Consolas", "Lucida Console", "Courier New", monospace !important;
  font-variant-ligatures: none !important;
  font-feature-settings: "zero" 1 !important;
}
h1, h2, h3, h4, h5, h6, p, li, dt, dd, label, summary,
span, strong, em, b, i, blockquote, th, td, cite, caption,
.article-title, .article-excerpt, .article-description, .headline,
.text-black, .text-dark, .text-gray, .text-grey, .text-muted,
.text-secondary, .text-body {
  color: #b7ffce !important;
}
a span, a strong, button span, button strong,
[role="button"] span, [role="menuitem"] span {
  color: inherit !important;
}
time, figcaption, small, .byline, .article-meta, .author-meta, .breadcrumb {
  color: #9ee5b6 !important;
}
a {
  color: #68ffa3 !important;
  text-decoration-color: rgba(69,255,137,.65) !important;
}
a:hover { color: #b5ffd1 !important; }
::selection { background: rgba(0,255,102,.35) !important; color: #f5fff7 !important; }

/* Navigation and footer glass. Article headers inherit their own surface. */
body > header, #site-header, #masthead, .site-header, .global-header,
[role="banner"], body > footer, #site-footer, .site-footer, [role="contentinfo"] {
  background: rgba(1,20,9,.58) !important;
  color: #d9ffe6 !important;
  border-color: rgba(24,241,106,.22) !important;
  -webkit-backdrop-filter: blur(11px) saturate(125%) !important;
  backdrop-filter: blur(11px) saturate(125%) !important;
}
nav { color: #d9ffe6 !important; border-color: rgba(28,240,102,.36) !important; }
nav a, [role="navigation"] a { color: #c0ffd5 !important; }
nav a:hover, nav a[aria-current="page"], nav a[aria-expanded="true"],
[role="navigation"] a:hover, [role="navigation"] a[aria-current="page"] {
  background-color: rgba(17,117,53,.40) !important;
  color: #effff4 !important;
  box-shadow: inset 2px 0 0 rgba(0,255,102,.76), 0 0 10px rgba(0,255,102,.09) !important;
}
/* The artwork casts the glow behind its silhouette. */
header a[href="/"] img, header a[href="/"] svg,
header a[aria-label="Snopes"] img, header a[aria-label="Snopes"] svg,
nav a[href="/"] img, nav a[href="/"] svg,
a.site-logo img, a.site-logo svg, a.header-logo img, a.header-logo svg,
#site-logo img, #site-logo svg,
img.site-logo, svg.site-logo, img.header-logo, svg.header-logo,
img#site-logo, svg#site-logo, img[alt="Snopes"], img[alt="Snopes logo"] {
  filter: drop-shadow(0 0 3px #00ff66) drop-shadow(0 0 8px rgba(0,255,102,.95)) drop-shadow(0 0 17px rgba(0,255,102,.75)) !important;
}
a.site-logo, a.header-logo, a#site-logo {
  color: #7fffac !important;
  text-shadow: 0 0 5px #00ff66, 0 0 14px rgba(0,255,102,.85) !important;
}
header button svg, nav button svg { color: #79ffaa !important; }

/* Cards, story pages, related stories and sidebar modules. */
main article, [role="main"] article, .article-card, .post-card, .story-card,
.fact-check-card, .news-card, .search-result, .related-content,
.article-body, .article-content, .claim, .newsletter-signup, .newsletter-box,
aside, [role="complementary"] {
  background: linear-gradient(135deg, rgba(17,92,49,.33) 0%, rgba(5,47,27,.45) 49%, rgba(1,24,14,.64) 100%) rgba(3,39,22,.50) !important;
  color: #d9ffe6 !important;
  border-radius: 21px !important;
  border-color: rgba(28,240,102,.36) !important;
  box-shadow: inset 0 0 0 1px rgba(76,255,137,.51), inset 0 1px 0 rgba(178,255,199,.19), 0 8px 24px rgba(0,0,0,.21), 0 0 20px rgba(0,246,98,.10) !important;
}
.article-card, .post-card, .story-card, .fact-check-card, .news-card,
.search-result, .newsletter-box, aside {
  -webkit-backdrop-filter: blur(8px) !important;
  backdrop-filter: blur(8px) !important;
}
article .article-body, article .article-content {
  background: transparent !important;
  box-shadow: none !important;
}
.article-card:hover, .post-card:hover, .story-card:hover, .fact-check-card:hover,
.news-card:hover, .search-result:hover {
  box-shadow: inset 0 0 0 1px rgba(46,255,120,.68), 0 0 14px rgba(0,234,88,.15) !important;
}
blockquote {
  background-color: rgba(4,45,22,.44) !important;
  border-left-color: #00e85c !important;
}
table th, table td { border-color: rgba(49,211,110,.28) !important; }
table th { background-color: rgba(5,48,21,.82) !important; }
table tr:nth-child(even) { background-color: rgba(2,27,13,.38) !important; }
pre { background-color: rgba(1,17,9,.92) !important; color: #bfffd0 !important; }
hr { border-color: rgba(38,241,108,.25) !important; }

/* Elevated navigation and readable dropdowns. */
dialog, [role="dialog"], [role="alertdialog"], [role="menu"], [role="listbox"],
[role="tooltip"], .dropdown-menu, .submenu, .sub-menu, .mobile-menu,
.mobile-nav, .search-overlay, .search-modal, .modal-content,
nav [aria-expanded="true"] + ul,
#onetrust-banner-sdk, #onetrust-pc-sdk {
  background: rgba(2,23,11,.97) !important;
  border-color: rgba(34,255,112,.41) !important;
  color: #d9ffe6 !important;
  box-shadow: 0 12px 35px rgba(0,0,0,.62), 0 0 18px rgba(0,180,67,.14) !important;
  -webkit-backdrop-filter: blur(19px) saturate(125%) !important;
  backdrop-filter: blur(19px) saturate(125%) !important;
}
[role="menuitem"], [role="menuitemradio"], [role="menuitemcheckbox"],
[role="option"], [role="tab"] { color: #cef9dc !important; }
[role="menuitem"]:hover, [role="menuitemradio"]:hover, [role="menuitemcheckbox"]:hover,
[role="option"]:hover, [role="option"][aria-selected="true"],
[role="menuitem"][data-highlighted], [role="option"][data-highlighted],
[role="tab"][aria-selected="true"] {
  background-color: rgba(12,103,43,.72) !important;
  color: #f0fff5 !important;
}

/* Search, account, newsletter and site action controls. */
input[type="text"], input[type="search"], input[type="email"], input[type="password"],
input[type="url"], input[type="tel"], input[type="number"], input:not([type]),
textarea, select, [role="textbox"] {
  background: rgba(4,43,20,.95) !important;
  border-color: rgba(48,255,126,.42) !important;
  color: #effff3 !important;
  caret-color: #38ff82 !important;
}
input::placeholder, textarea::placeholder { color: #a6efbb !important; opacity: 1 !important; }
option, optgroup { background-color: #03190b !important; color: #d9ffe6 !important; }
button, a[role="button"], .button, .btn, input[type="button"], input[type="reset"] {
  background-color: rgba(4,57,26,.88) !important;
  border-color: rgba(28,240,102,.36) !important;
  color: #b7ffd0 !important;
}
button:hover, a[role="button"]:hover, .button:hover, .btn:hover,
input[type="button"]:hover, input[type="reset"]:hover {
  background-color: rgba(12,91,39,.56) !important;
  border-color: rgba(30,255,109,.50) !important;
  box-shadow: 0 0 14px rgba(0,234,88,.15) !important;
}
button[type="submit"], input[type="submit"] {
  background: rgba(4,57,26,.88) !important;
  color: #b7ffce !important;
  box-shadow: 0 0 12px rgba(0,255,102,.32) !important;
}
button[type="submit"]:hover, input[type="submit"]:hover { background-color: rgba(12,91,39,.78) !important; }
button:disabled, input:disabled, [aria-disabled="true"][role="button"] { opacity: .65 !important; }
a:focus, button:focus, input:focus, select:focus,
textarea:focus, summary:focus, [tabindex]:focus {
  outline: 2px solid #00ff66 !important;
  outline-offset: 2px !important;
}
input[type="checkbox"], input[type="radio"] { accent-color: #00e85c !important; }
* { scrollbar-color: rgba(29,191,83,.53) rgba(0,18,7,.18); scrollbar-width: thin; }
*::-webkit-scrollbar { width: 8px; height: 8px; }
*::-webkit-scrollbar-track { background: rgba(0,18,7,.18) !important; }
*::-webkit-scrollbar-thumb { background: rgba(29,191,83,.53) !important; border-radius: 10px; }

/* Mobile search uses the site-provided IDs. */
#mobile_search_wrap {
  background-color: rgba(2,24,13,.43) !important;
  background-image: linear-gradient(145deg, rgba(13,92,47,.35), rgba(4,47,25,.28) 40%, rgba(1,19,11,.59)) !important;
  color: #d9ffe6 !important;
  border-color: rgba(28,240,102,.36) !important;
  box-shadow: inset 0 0 0 1px rgba(28,240,102,.36), 0 0 20px rgba(0,246,98,.10) !important;
  -webkit-backdrop-filter: blur(11px) saturate(125%) !important;
  backdrop-filter: blur(11px) saturate(125%) !important;
}
#mobile_search_wrap .search_slogan {
  color: #d9ffe6 !important;
  font-family: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", "Consolas", "Lucida Console", "Courier New", monospace !important;
}
#mobile_search_wrap #outer_searchbox_container {
  background: rgba(4,43,20,.95) !important;
  border-color: rgba(45,255,118,.50) !important;
  border-radius: 12px !important;
  box-shadow: inset 0 0 0 1px rgba(45,255,118,.50) !important;
}
#mobile_search_wrap .navbar_search_form,
#mobile_search_wrap input.search_input {
  background: transparent !important;
  border-color: transparent !important;
  color: #d9ffe6 !important;
}
#mobile_search_wrap input.search_input::placeholder {
  color: #9ee5b6 !important;
  opacity: 1 !important;
}
#mobile_search_wrap button.searchbox_icon {
  background: rgba(4,57,26,.88) !important;
  border-color: rgba(28,240,102,.36) !important;
  color: #7fffac !important;
  box-shadow: none !important;
}
#mobile_search_wrap button.searchbox_icon:hover,
#mobile_search_wrap button.searchbox_icon:focus {
  background: rgba(12,91,39,.56) !important;
  color: #d9ffe6 !important;
  box-shadow: 0 0 12px rgba(0,255,102,.32) !important;
}

/* One glass surface on the primary content landmark. */
main, [role="main"] {
  background-color: rgba(3,39,22,.50) !important;
  background-image: linear-gradient(135deg, rgba(17,92,49,.33), rgba(5,47,27,.45) 49%, rgba(1,24,14,.64)) !important;
  border-radius: 21px !important;
  box-shadow: inset 0 0 0 1px rgba(76,255,137,.51), 0 8px 24px rgba(0,0,0,.21), 0 0 20px rgba(0,246,98,.10) !important;
}

/* Inset rings add a visible border without resizing the controls. */
button, [role="button"], .button, .btn,
input[type="button"], input[type="reset"], input[type="submit"],
button[type="submit"], #mobile_search_wrap button.searchbox_icon {
  border-color: rgba(0,255,102,.66) !important;
  box-shadow: inset 0 0 0 1px rgba(0,255,102,.66), 0 0 8px rgba(0,255,102,.38) !important;
}
button:hover, [role="button"]:hover, .button:hover, .btn:hover,
input[type="button"]:hover, input[type="reset"]:hover, input[type="submit"]:hover,
button[type="submit"]:hover, #mobile_search_wrap button.searchbox_icon:hover,
#mobile_search_wrap button.searchbox_icon:focus,
nav a:hover, [role="navigation"] a:hover, [role="menuitem"]:hover,
[role="menuitemradio"]:hover, [role="menuitemcheckbox"]:hover,
[role="option"]:hover, [role="tab"]:hover, summary:hover,
main article:hover, [role="main"] article:hover, .article-card:hover,
.post-card:hover, .story-card:hover, .fact-check-card:hover,
.news-card:hover, .search-result:hover {
  border-color: #00ff66 !important;
  box-shadow: inset 0 0 0 1px #00ff66, 0 0 9px rgba(0,255,102,.58), 0 0 18px rgba(0,255,102,.30) !important;
}
main a:hover, [role="main"] a:hover, footer a:hover {
  outline: 1px solid #00ff66 !important;
  outline-offset: 2px !important;
  box-shadow: 0 0 9px rgba(0,255,102,.58) !important;
}

/* Ad-block notice. Use stable classes so generated IDs can change. */
.adblock_notice {
  background: rgba(1,20,10,.78) !important;
}
.adblock_notice .adblock_card {
  background: linear-gradient(135deg, rgba(17,92,49,.33), rgba(5,47,27,.45) 49%, rgba(1,24,14,.64)) rgba(2,23,11,.97) !important;
  color: #d9ffe6 !important;
  border-color: rgba(76,255,137,.51) !important;
  border-radius: 21px !important;
  box-shadow: inset 0 0 0 1px rgba(76,255,137,.51), 0 12px 35px rgba(0,0,0,.62), 0 0 24px rgba(0,255,102,.24) !important;
  font-family: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", "Consolas", "Lucida Console", "Courier New", monospace !important;
}
.adblock_notice .adblock_logo {
  filter: drop-shadow(0 0 4px #00ff66) drop-shadow(0 0 12px rgba(0,255,102,.78)) !important;
}
.adblock_notice .adblock_title,
.adblock_notice .instructions_title_inline {
  color: #7fffac !important;
}
.adblock_notice .adblock_card p,
.adblock_notice .instruction_list li {
  color: #d9ffe6 !important;
}
.adblock_notice .instructions_panel {
  background: rgba(4,32,15,.97) !important;
  border-color: rgba(45,255,118,.50) !important;
  box-shadow: inset 0 0 0 1px rgba(45,255,118,.36) !important;
}
.adblock_notice .adblock_btn,
.adblock_notice .refresh_btn,
.adblock_notice .extension_tab {
  background: rgba(4,57,26,.88) !important;
  color: #b7ffce !important;
  border-color: rgba(0,255,102,.66) !important;
  box-shadow: inset 0 0 0 1px rgba(0,255,102,.66), 0 0 8px rgba(0,255,102,.30) !important;
}
.adblock_notice .adblock_btn,
.adblock_notice .adblock_login_link {
  font-family: inherit !important;
}
.adblock_notice .extension_icon {
  background: rgba(2,23,11,.97) !important;
  color: #7fffac !important;
}
.adblock_notice .adblock_btn:hover,
.adblock_notice .adblock_btn:focus,
.adblock_notice .refresh_btn:hover,
.adblock_notice .refresh_btn:focus,
.adblock_notice .extension_tab:hover,
.adblock_notice .extension_tab:focus,
.adblock_notice .extension_tab.active {
  background: rgba(12,91,39,.78) !important;
  color: #d9ffe6 !important;
  border-color: #00ff66 !important;
  box-shadow: inset 0 0 0 1px #00ff66, 0 0 12px rgba(0,255,102,.52) !important;
}
.adblock_notice .adblock_login_link,
.adblock_notice .instruction_list a {
  color: #68ffa3 !important;
}
.adblock_notice .adblock_login_link:hover,
.adblock_notice .instruction_list a:hover {
  color: #d9ffe6 !important;
  text-shadow: 0 0 8px rgba(0,255,102,.70) !important;
}

/* Login, recovery, and sign-up share the same modal. */
.modal.modal-type-login {
  background: linear-gradient(135deg, rgba(17,92,49,.38), rgba(1,24,14,.64)) rgba(2,23,11,.94) !important;
  color: #d9ffe6 !important;
  border-color: rgba(76,255,137,.62) !important;
  border-radius: 21px !important;
  box-shadow: inset 0 0 0 1px rgba(76,255,137,.62), 0 12px 35px rgba(0,0,0,.62), 0 0 24px rgba(0,255,102,.24) !important;
  backdrop-filter: blur(12px) !important;
  font-family: "Cascadia Mono", "Cascadia Code", "JetBrains Mono", "Consolas", "Lucida Console", "Courier New", monospace !important;
}
.modal.modal-type-login .login-form,
.modal.modal-type-login .top_logo_cont,
.modal.modal-type-login .top_text_cont,
.modal.modal-type-login #form-login-wrapper {
  background: transparent !important;
}
.modal.modal-type-login .logo_cont img {
  filter: drop-shadow(0 0 4px #00ff66) drop-shadow(0 0 12px rgba(0,255,102,.78)) !important;
}
.modal.modal-type-login .top_title,
.modal.modal-type-login .setup-method-title {
  color: #7fffac !important;
}
.modal.modal-type-login .top_desc,
.modal.modal-type-login .setup-method-desc,
.modal.modal-type-login .separator {
  color: #9ee5b6 !important;
}
.modal.modal-type-login .setup-method-form,
.modal.modal-type-login .setup-method-item,
.modal.modal-type-login .setup-logged-in-banner,
.modal.modal-type-login .free-upgrade-perks,
.modal.modal-type-login .member_main_cont,
.modal.modal-type-login .change_plan_box {
  background: rgba(4,32,15,.92) !important;
  color: #d9ffe6 !important;
  border-color: rgba(45,255,118,.50) !important;
  box-shadow: inset 0 0 0 1px rgba(45,255,118,.36) !important;
}
.modal.modal-type-login .input_box_wrap,
.modal.modal-type-login input[type="text"],
.modal.modal-type-login input[type="email"],
.modal.modal-type-login input[type="password"],
.modal.modal-type-login input[type="tel"],
.modal.modal-type-login select {
  background: #082719 !important;
  border-color: rgba(45,255,118,.55) !important;
  color: #d9ffe6 !important;
}
.modal.modal-type-login .input_box_wrap {
  box-shadow: inset 0 0 0 1px rgba(45,255,118,.55) !important;
}
.modal.modal-type-login .input_box_wrap input {
  background: transparent !important;
}
.modal.modal-type-login input::placeholder {
  color: #9ee5b6 !important;
  opacity: 1 !important;
}
.modal.modal-type-login .input_box_wrap svg,
.modal.modal-type-login .login-method-btn svg {
  color: #7fffac !important;
}
.modal.modal-type-login input:-webkit-autofill {
  -webkit-text-fill-color: #d9ffe6 !important;
  box-shadow: inset 0 0 0 100px #082719 !important;
}
.modal.modal-type-login input:focus,
.modal.modal-type-login select:focus,
.modal.modal-type-login button:focus,
.modal.modal-type-login a:focus {
  outline: 2px solid #00ff66 !important;
  outline-offset: 2px !important;
}
.modal.modal-type-login a {
  color: #68ffa3 !important;
}
.modal.modal-type-login button,
.modal.modal-type-login a.button {
  background: #103a24 !important;
  color: #d9ffe6 !important;
  border-color: rgba(0,255,102,.66) !important;
  box-shadow: inset 0 0 0 1px rgba(0,255,102,.66), 0 0 8px rgba(0,255,102,.32) !important;
}
.modal.modal-type-login button:hover,
.modal.modal-type-login a.button:hover {
  background: #195635 !important;
  color: #e1ffeb !important;
  border-color: #00ff66 !important;
  box-shadow: inset 0 0 0 1px #00ff66, 0 0 12px rgba(0,255,102,.52) !important;
}
.modal.modal-type-login .error_cont,
.modal.modal-type-login .error_cont span,
.modal.modal-type-login #setup-phone-verify-error {
  color: #ffb3b3 !important;
}
.modal.modal-type-login .success_cont span {
  color: #7fffac !important;
}

/* Keep the login email field dark even when the browser autofills it. */
.modal.modal-type-login #user_login_email .input_box_wrap,
.modal.modal-type-login #modal-login-email {
  background: #03120b !important;
}
.modal.modal-type-login #modal-login-email {
  color: #edfff2 !important;
  caret-color: #7fffac !important;
  -webkit-text-fill-color: #edfff2 !important;
}
.modal.modal-type-login #modal-login-email::placeholder {
  color: #b7e8c8 !important;
  -webkit-text-fill-color: #b7e8c8 !important;
  opacity: 1 !important;
}
.modal.modal-type-login #modal-login-email:-webkit-autofill {
  box-shadow: inset 0 0 0 100px #03120b !important;
}

/* Header actions and topic chips shown above the feed. */
header a[href^="/support"],
header a[href^="/membership"],
header a[href^="/login"],
header a[href^="/log-in"],
nav a[href^="/support"],
nav a[href^="/membership"],
[role="banner"] a[href^="/support"],
a[onclick*="user_menu_toggle"],
button[onclick*="user_menu_toggle"],
header [class*="login_button"],
header [class*="membership_button"],
.navbar_search_form .searchbox_icon,
a[href^="/tag/"],
a[href^="/tags/"],
a[href^="/topic/"],
a[href^="/topics/"],
a[href^="https://www.snopes.com/tag/"],
.trending-tags a,
.trending_tags a,
.topic-chip,
.topic_chip,
.tag-pill,
.tag_pill {
  background: #0b2c1c !important;
  color: #d9ffe6 !important;
  border-color: rgba(0,255,102,.65) !important;
  box-shadow: inset 0 0 0 1px rgba(0,255,102,.65), 0 0 8px rgba(0,255,102,.28) !important;
}
header a[href^="/support"]:hover,
header a[href^="/membership"]:hover,
header a[href^="/login"]:hover,
header a[href^="/log-in"]:hover,
nav a[href^="/support"]:hover,
nav a[href^="/membership"]:hover,
[role="banner"] a[href^="/support"]:hover,
a[onclick*="user_menu_toggle"]:hover,
button[onclick*="user_menu_toggle"]:hover,
header [class*="login_button"]:hover,
header [class*="membership_button"]:hover,
.navbar_search_form .searchbox_icon:hover,
a[href^="/tag/"]:hover,
a[href^="/tags/"]:hover,
a[href^="/topic/"]:hover,
